  check (vendor in ('greenhouse', 'lever', 'lever-eu', 'ashby', 'workable', 'remote-com'));

-- ===== supabase/migrations/20261021090000_jobkit_setup.sql =====
-- First-run setup: single owner of this jobkit instance + per-user LLM settings.
-- Both tables are service-role only (RLS on, no policies): the browser never reads them.

create table if not exists public.jobkit_instance (
  id smallint primary key default 1 check (id = 1),
  owner_user_id uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.jobkit_instance enable row level security;

create table if not exists public.jobkit_settings (
  user_id uuid primary key references auth.users (id) on delete cascade,
  llm_provider text not null default 'openrouter',
  llm_base_url text not null default '',
  llm_model text not null default '',
  -- "enc:v1:" + base64url(iv | AES-256-GCM ciphertext), key = Worker secret SETTINGS_ENC_KEY
  llm_key_enc text not null default '',
  updated_at timestamptz not null default now(),
  constraint jobkit_settings_provider_check check (llm_provider in ('openrouter', 'openai', 'custom'))
);
alter table public.jobkit_settings enable row level security;

-- ===== supabase/migrations/20261021150000_jobkit_scan_targets_hq.sql =====
-- Optional company headquarters shown as a chip on the Following tab (e.g. "Paris, France"). Empty = unknown.
alter table public.jobkit_scan_targets
  add column if not exists hq text not null default '';

-- ===== supabase/migrations/20261021160000_jobkit_jobs_suitability.sql =====
-- Cached suitability check per job (role constraints such as "no hands-on coding"):
-- {ok, reason, model, key, checked_at}. ok=false hides the job from Jobs by default. Null = not checked.
alter table public.jobkit_jobs
  add column if not exists suitability jsonb;

-- ===== supabase/migrations/20261021170000_jobkit_scan_targets_industry.sql =====
-- Optional short industry label per watched company (e.g. "Fintech"), shown as a chip on Following. Empty = unknown.
alter table public.jobkit_scan_targets
  add column if not exists industry text not null default '';

-- ===== supabase/migrations/20261021180000_jobkit_scan_teamtailor.sql =====
-- Teamtailor career sites (slug = the career-site host; read from its public jobs.rss feed).
alter table public.jobkit_scan_targets drop constraint if exists jobkit_scan_targets_vendor_check;
alter table public.jobkit_scan_targets drop constraint if exists jobkit_scan_targets_vendor_check;
alter table public.jobkit_scan_targets add constraint jobkit_scan_targets_vendor_check
  check (vendor in ('greenhouse', 'lever', 'lever-eu', 'ashby', 'workable', 'remote-com', 'teamtailor'));

-- ===== supabase/migrations/20261021190000_jobkit_settings_anthropic.sql =====
-- Claude (the Anthropic API) joins the LLM providers chosen in /setup.
alter table public.jobkit_settings drop constraint if exists jobkit_settings_provider_check;
alter table public.jobkit_settings drop constraint if exists jobkit_settings_provider_check;
alter table public.jobkit_settings add constraint jobkit_settings_provider_check
  check (llm_provider in ('openrouter', 'openai', 'anthropic', 'custom'));

-- ===== supabase/migrations/20261021200000_jobkit_engine_bridge.sql =====
-- Bridge to the jobkit engine (the Python CLI). Only the service role uses these tables (no policies).

-- Postings the engine found on boards the Worker can't read; each scan scores and then deletes them.
create table if not exists public.jobkit_external_openings (
  user_id uuid not null references auth.users (id) on delete cascade,
  external_key text not null,
  company text not null,
  title text not null,
  url text not null,
  description text not null default '',
  location text not null default '',
  source text not null default '',
  found_at timestamptz not null default now(),
  primary key (user_id, external_key)
);
alter table public.jobkit_external_openings enable row level security;

-- The engine's merge snapshot for syncing applications.md with jobkit_apps, shared by every machine that syncs.
create table if not exists public.jobkit_sync_state (
  user_id uuid primary key references auth.users (id) on delete cascade,
  state jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);
alter table public.jobkit_sync_state enable row level security;

-- Tell the Data API (PostgREST) about the new tables.
notify pgrst, 'reload schema';
